import { cli } from 'cli-forge';

cli('basic-cli').command('hello', {
  builder: (args) =>
   args.option('name', {
     type: 'string',
   }),
  handler: (args) => {
    console.log(`Hello, ${args.name}!`);
  }).forge();

import { getCommandContext } from 'cli-forge/context';
import { app } from './cli';

const ctx = getCommandContext(app);
const db = ctx.inject('db');

function withVerbose<T extends UnknownCLI>(cli: T) {
  return cli.option('verbose', { type: 'boolean' });
}

